<script setup>
import { ref, onMounted } from 'vue'
import { useRoute } from 'vue-router'
import { computed } from 'vue'

const route = useRoute()
const kindergarten = ref(null)
const kindergartenId = route.params._id || route.params.kindergartenId
const activeTab = ref('Information') 


onMounted(async () => {
  const res = await fetch(`/api/kindergartens/detail/${kindergartenId}`)
  if (res.ok) {
    kindergarten.value = await res.json()
  }
})


function renderStars(score) {
  const filled = '<span style="color:gold;">★</span>'.repeat(score)
  const empty = '<span style="color:lightgray;">☆</span>'.repeat(5 - score)
  return filled + empty
}
// Deduplicate facilities
const distinctFacilities = computed(() => {
  if (!kindergarten.value?.FACILITIES_ENGLISH) return []
  return [...new Set(kindergarten.value.FACILITIES_ENGLISH)]
})

// Chunk into groups of 3
const chunkedFacilities = computed(() => {
  const chunks = []
  for (let i = 0; i < distinctFacilities.value.length; i += 3) {
    chunks.push(distinctFacilities.value.slice(i, i + 3))
  }
  return chunks
})

const sortedImportantDates = computed(() => {
  return [...importantDates.value].sort((a, b) => {
    return new Date(a.date) - new Date(b.date);
  });
});
const facilityImages = {
  "Rest Areas": 
    "data:image/jpeg;base64,",
  "Reading Corners": "data:image/jpeg;base64,",
  "Play Areas": "data:image/jpeg;base64,",
  "Nature Trails": "https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQ9Yky3Peg2r6C-6GNdABAzQRDny5fbmZr3-w&s",
  "STEM Room":  "data:image/jpeg;base64,"
  ,
  "Sports Areas": "data:image/jpeg;base64,"
  ,
  "Art and Craft Stations": "data:image/jpeg;base64,"
  ,
  "Music Room":  "data:image/jpeg;base64,"
  ,
  "Outdoor Classrooms": "data:image/jpeg;base64,"
  ,
  "Playground": "data:image/jpeg;base64,"
  ,
  "Art Room":  "data:image/jpeg;base64,"
  ,
  "Gardens":  "data:image/jpeg;base64,"
  
}

const activityImages = {
  "Environmental Cleanup Activity":  "data:image/jpeg;base64,"
  ,
  "Concert":  "data:image/jpeg;base64,"
  ,
  "Science Fair":  "data:image/jpeg;base64,"
  ,
  "Learning Workshop":  "data:image/jpeg;base64,"
  ,
  "Festival Celebration":  "data:image/jpeg;base64,"
  ,
  "Writing Competition":  "https://yourcdn.com/activities/writing-competition.jpgdata:image/jpeg;base64,"
  ,
  "Craft Workshop":  "data:image/jpeg;base64,"
  ,
  "Parent-Teacher Meeting": "data:image/jpeg;base64,"
  ,
  "Community Service Activities": "data:image/jpeg;base64,"
  ,
  "Internship Sharing Session":  "data:image/jpeg;base64,"
  ,
  "Environmental Awareness Campaign":  "data:image/jpeg;base64,"
  ,
  "Mini Marathon": "data:image/jpeg;base64,"
  ,
  "Academic Seminar":  "data:image/jpeg;base64,"
  ,
  "Painting Competition": "data:image/jpeg;base64,"
  ,
  "Campus Tour":  "data:image/jpeg;base64,"
  ,
  "Cultural Exchange Activities": "data:image/jpeg;base64,"
  ,
  "Book Club":  "data:image/jpeg;base64,"
  ,
  "Art Exhibition":  "data:image/jpeg;base64,"
  ,
  "School Sports Day": "data:image/jpeg;base64,"
  
