        <li class="list-group-item">
          <i class="bi bi-people-fill me-2 text-secondary"></i>
          <strong>Gender:</strong> {{ kindergarten?.STUDENTS_GENDER }}
        </li>
        <li class="list-group-item">
          <i class="bi bi-cash-stack me-2 text-success"></i>
